components.css:
.ds-mod { background: var(--tile, #ffffff); border: 1px solid var(--hairline, #e8e8e8); border-bottom: 0; font-family: 'Inter Variable', system-ui, sans-serif; color: var(--ink, #000000); }
.ds-mod-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 6px 8px; background: var(--wash, #f5f5f5); border-bottom: 1px solid var(--ink, #000000); }
.ds-mod-title { font-size: 0.8125rem; font-weight: 700; }
.ds-mod-note { font-size: 0.75rem; font-variant-numeric: tabular-nums; }
.ds-mod-body { padding: 6px 8px; font-size: 0.8125rem; }
.ds-mod > .ds-mod-body:last-child { border-bottom: 1px solid var(--hairline, #e8e8e8); }

.ds-tile { position: relative; display: flex; flex-direction: column; gap: 4px; width: 154px; padding: 6px 8px 8px; text-align: left; background: var(--tile, #ffffff); border: 1px solid var(--hairline, #e8e8e8); border-radius: 0; cursor: pointer; font-family: 'Inter Variable', system-ui, sans-serif; color: var(--ink, #000000); transition: background 100ms cubic-bezier(0.4, 0, 0.2, 1), border-color 100ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-tile:hover { background: var(--wash, #f5f5f5); border-color: var(--ink, #000000); }
.ds-tile:focus-visible { outline: 2px solid var(--ink, #000000); outline-offset: -2px; }
.ds-tag { align-self: flex-start; display: inline-flex; align-items: center; height: 15px; padding: 0 5px; font-size: 0.75rem; font-weight: 600; color: var(--tile, #ffffff); background: var(--utility, #cc0d0d); }
.ds-tile-name { font-size: 0.8125rem; font-weight: 500; line-height: 1.2; }
.ds-tile-foot { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-top: auto; }
.ds-tile-stock { font-size: 0.75rem; font-variant-numeric: tabular-nums; }
.ds-tile-price { font-size: 0.8125rem; font-weight: 600; color: var(--utility, #cc0d0d); font-variant-numeric: tabular-nums; }

.ds-tile--out { cursor: not-allowed; }
.ds-tile--out:hover { background: var(--tile, #ffffff); border-color: var(--hairline, #e8e8e8); }
.ds-tile--out .ds-tile-name, .ds-tile--out .ds-tile-price { text-decoration: line-through; text-decoration-thickness: 1px; }
.ds-tag--quiet { color: var(--ink, #000000); background: var(--wash, #f5f5f5); border: 1px solid var(--hairline, #e8e8e8); }

.ds-tabs { display: flex; align-items: stretch; font-family: 'Inter Variable', system-ui, sans-serif; }
.ds-tab { display: inline-flex; align-items: center; gap: 6px; padding: 6px 10px; font-size: 0.8125rem; color: var(--ink, #000000); background: var(--tile, #ffffff); border-right: 1px solid var(--hairline, #e8e8e8); text-decoration: none; white-space: nowrap; transition: background 100ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-tab:hover { background: var(--wash, #f5f5f5); }
.ds-tab--on, .ds-tab--on:hover { background: var(--utility, #cc0d0d); color: var(--tile, #ffffff); font-weight: 600; }
.ds-tab-n { font-size: 0.75rem; font-variant-numeric: tabular-nums; }

.ds-field { display: flex; flex-direction: column; gap: 3px; font-family: 'Inter Variable', system-ui, sans-serif; }
.ds-label { font-size: 0.75rem; font-weight: 600; color: var(--ink, #000000); }
.ds-input { height: 26px; width: 100%; padding: 0 6px; font-family: inherit; font-size: 0.8125rem; font-variant-numeric: tabular-nums; color: var(--ink, #000000); background: var(--tile, #ffffff); border: 1px solid var(--hairline, #e8e8e8); border-radius: 0; outline: none; caret-color: var(--utility, #cc0d0d); transition: border-color 100ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-input:hover { border-color: var(--ink, #000000); }
.ds-input:focus-visible { border-color: var(--ink, #000000); outline: 2px solid var(--ink, #000000); outline-offset: -2px; }
.ds-input[aria-invalid='true'] { border-color: var(--utility, #cc0d0d); outline: 2px solid var(--utility, #cc0d0d); outline-offset: -2px; }

.ds-methods { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 4px; font-family: 'Inter Variable', system-ui, sans-serif; }
.ds-method { display: flex; align-items: center; justify-content: center; height: 26px; font-size: 0.8125rem; font-weight: 500; color: var(--ink, #000000); background: var(--tile, #ffffff); border: 1px solid var(--hairline, #e8e8e8); border-radius: 0; cursor: pointer; transition: background 100ms cubic-bezier(0.4, 0, 0.2, 1), border-color 100ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-method:hover { background: var(--wash, #f5f5f5); }
.ds-method input { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0, 0, 0, 0); }
.ds-method:focus-within { outline: 2px solid var(--ink, #000000); outline-offset: -2px; }
.ds-method:has(input:checked) { background: var(--ink, #000000); color: var(--tile, #ffffff); border-color: var(--ink, #000000); font-weight: 600; }

.ds-fig { font-family: 'Inter Variable', system-ui, sans-serif; }
.ds-fig-label { margin: 0; font-size: 0.75rem; font-weight: 600; color: var(--ink, #000000); }
.ds-fig-value { margin: 0; font-size: 1.25rem; font-weight: 700; line-height: 1.1; font-variant-numeric: tabular-nums; color: var(--ink, #000000); }
